-- Run this ONCE against your existing pr-course-db to add the internal
-- portal (internal.pentictonrobotics.ca). Nothing already in the course
-- portal is changed or lost.
--
-- 1. Marks each existing stream as belonging to the course site.
-- 2. Adds the seven internal portal sections with their starting groups
--    and pages. Anything marked as a draft stays hidden until you publish it
--    in the Admin Panel.

ALTER TABLE streams ADD COLUMN site TEXT NOT NULL DEFAULT 'course';

-- Internal portal sections, groups, and starter pages.
INSERT OR IGNORE INTO streams (stream_key, name, description, sort_order, site) VALUES ('roles', 'Role Handbooks', 'A handbook and a resources library for every role on the team. Pick a role to find its training, reports, job description, and duties.', 10, 'internal');
INSERT OR IGNORE INTO streams (stream_key, name, description, sort_order, site) VALUES ('parents', 'Parent Volunteer Handbook', 'Everything parent volunteers need to support the team: training, what is expected of you, resources, and who to contact.', 11, 'internal');
INSERT OR IGNORE INTO streams (stream_key, name, description, sort_order, site) VALUES ('mentors', 'Mentor Handbook', 'Training, expectations, and resources for mentors working with Penticton Robotics students.', 12, 'internal');
INSERT OR IGNORE INTO streams (stream_key, name, description, sort_order, site) VALUES ('how-it-runs', 'How It Runs', 'How the Penticton Robotics program is organized: the Prep Team and Competition Team, course credit and grading, org charts, and team policies.', 13, 'internal');
INSERT OR IGNORE INTO streams (stream_key, name, description, sort_order, site) VALUES ('prep-team', 'Prep Team', 'Resources for Prep Team students and mentors: onboarding, the learning portal, Google Classroom, and how to move up to the Competition Team.', 14, 'internal');
INSERT OR IGNORE INTO streams (stream_key, name, description, sort_order, site) VALUES ('comp-team', 'Competition Team', 'Resources for Competition Team students: onboarding and the platforms the team uses.', 15, 'internal');
INSERT OR IGNORE INTO streams (stream_key, name, description, sort_order, site) VALUES ('career', 'Resume and Career', 'Certifications, FIRST scholarships, and Penticton scholarships to help students build their resumes and plan what comes after high school.', 16, 'internal');

