INSERT INTO units (stream_id, unit_label, title, sort_order, published) SELECT id, '', 'Prep Team and Competition Team', 1, 1 FROM streams WHERE stream_key = 'how-it-runs' AND NOT EXISTS (SELECT 1 FROM units u WHERE u.stream_id = streams.id AND u.title = 'Prep Team and Competition Team');
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT u.id, 'Prep Team and Competition Team', '<p>Penticton Robotics is divided into two cohorts: the Prep Team and the Competition Team. Each cohort meets on different days.</p><h3>Prep Team</h3><p>The Prep Team is where students complete the learning pathway and build the foundational knowledge and skills they need. Students choose one of three streams: build, programming, or business. Every student begins here, and the Prep Team is the required starting point for joining the Competition Team.</p><h3>Competition Team</h3><p>The Competition Team is where students apply and continue developing those skills in a less structured, more demanding, student-led environment.</p><p>Along with developing foundational knowledge and skills, students build qualities that are essential on a less structured, student-led team, including initiative, reliability, and teamwork.</p>', 1, 1 FROM units u JOIN streams s ON s.id = u.stream_id WHERE s.stream_key = 'how-it-runs' AND u.title = 'Prep Team and Competition Team' AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = u.id AND l.title = 'Prep Team and Competition Team');
INSERT INTO units (stream_id, unit_label, title, sort_order, published) SELECT id, '', 'Course Credit and Grading', 2, 1 FROM streams WHERE stream_key = 'how-it-runs' AND NOT EXISTS (SELECT 1 FROM units u WHERE u.stream_id = streams.id AND u.title = 'Course Credit and Grading');
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT u.id, 'Course Credit', '<p>Both the Prep Team and the Competition Team are eligible for Princess Margaret Secondary School course credit. Students can choose whether they would like to officially register and receive graduation credits and a mark on their transcript, or participate without receiving credit. The learning experience is exactly the same either way. The decision to earn credits is entirely up to the student.</p><p>For students wanting a grade and credits, the accredited robotics course is open to students across School District 67. Students attending Summerland Secondary School or Penticton Secondary School are welcome to cross enrol at Princess Margaret.</p>', 1, 1 FROM units u JOIN streams s ON s.id = u.stream_id WHERE s.stream_key = 'how-it-runs' AND u.title = 'Course Credit and Grading' AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = u.id AND l.title = 'Course Credit');
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT u.id, 'Daily Reflection and Progress Log', '<p>Competition Team students complete the <strong>Daily Robotics Team Reflection</strong> at the end of each meeting. It is the daily self assessment that feeds the team''s marks sheet and the leaderboard.</p><ol><li>What did you work on today? Briefly describe what you accomplished or contributed.</li><li>How productive were you today? Stay focused and use time effectively.</li><li>What mark out of 100 do you believe you deserve for today''s work?</li><li>Why do you believe you deserve this mark? Think about effort, productivity, teamwork, and contribution.</li><li>What is one thing you want to accomplish next time? Set a goal or task for the next robotics meeting.</li></ol><p>The daily reflections also serve as each Competition Team student''s progress log. Prep Team students are assessed through their stream assignments.</p>', 1, 2 FROM units u JOIN streams s ON s.id = u.stream_id WHERE s.stream_key = 'how-it-runs' AND u.title = 'Course Credit and Grading' AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = u.id AND l.title = 'Daily Reflection and Progress Log');
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT u.id, 'Bonus Points', '<p>Students can earn bonus points on top of their daily marks:</p><ul><li><strong>10 points</strong> for every hour of robotics work done outside of class</li><li><strong>10 points</strong> for every $100 raised</li><li><strong>5 points</strong> each time a student gets a shout out in #appreciation</li></ul><p>Bonus points are recorded in the team''s marks sheet.</p>', 1, 3 FROM units u JOIN streams s ON s.id = u.stream_id WHERE s.stream_key = 'how-it-runs' AND u.title = 'Course Credit and Grading' AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = u.id AND l.title = 'Bonus Points');
INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT u.id, 'Grading Rubric', '<p><em>Draft. Review and edit before publishing.</em></p><p>The same four criteria are used for every student, every day, in both cohorts. They match the questions in the Daily Robotics Team Reflection.</p><h3>Effort</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Productivity</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Teamwork</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul><h3>Contribution</h3><ul><li>90 to 100: ____</li><li>75 to 89: ____</li><li>60 to 74: ____</li><li>Below 60: ____</li></ul>', 0, 4 FROM units u JOIN streams s ON s.id = u.stream_id WHERE s.stream_key = 'how-it-runs' AND u.title = 'Course Credit and Grading' AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = u.id AND l.title = 'Grading Rubric');
