INSERT INTO lessons (unit_id, title, content_html, published, sort_order) SELECT u.id, 'Learning Portal', '<p>The Prep Team learning portal holds the lessons, assignments, and resources for the Build, Programming, and Business streams.</p><p><a href="https://course.pentictonrobotics.ca" target="_blank" rel="noopener">Open the learning portal</a></p>', 1, 1 FROM units u JOIN streams s ON s.id = u.stream_id WHERE s.stream_key = 'prep-team' AND u.title = 'Learning Portal' AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.unit_id = u.id AND l.title = 'Learning Portal');
